import{_ as n,C as s,o as r,c as i,ag as e,E as a}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Checkout Deals","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/checkout-deals.md","filePath":"marketing/checkout-deals.md","lastUpdated":1787558413000}'),l={name:"marketing/checkout-deals.md"};function d(c,t,g,u,h,p){const o=s("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="checkout-deals" tabindex="-1">Checkout Deals <a class="header-anchor" href="#checkout-deals" aria-label="Permalink to &quot;Checkout Deals&quot;">​</a></h1><p>Checkout Deals are cart-level promotions — discounts and coupons that apply to the <strong>shopping cart</strong> rather than to a single product. Use them to reward a whole order (spend a threshold, get a discount), optionally behind a coupon code the customer enters at checkout.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to create a checkout deal, tab by tab</li><li>The four deal types and how coupons work</li><li>How to generate coupon codes and copy a deal</li></ul></div><h2 id="creating-a-checkout-deal" tabindex="-1">Creating a checkout deal <a class="header-anchor" href="#creating-a-checkout-deal" aria-label="Permalink to &quot;Creating a checkout deal&quot;">​</a></h2><p>From the Seller Panel, open <strong>Marketing → Checkout Deals</strong> and select <strong>Create Checkout Deal</strong>. Like product discounts, the form has three tabs — <strong>Deal</strong>, <strong>Details</strong>, and <strong>Advanced</strong>.</p><h3 id="deal" tabindex="-1">Deal <a class="header-anchor" href="#deal" aria-label="Permalink to &quot;Deal&quot;">​</a></h3><p>Choose what kind of reward the cart gets:</p>',7)),a(o,{src:"/images/checkout-deals/deal.png",alt:"Checkout deal — Deal tab"}),t[1]||(t[1]=e('<ul><li><strong>Percentage off</strong> — a percentage off the qualifying items.</li><li><strong>Fixed amount off the whole cart</strong> — a set amount off the cart total.</li><li><strong>Fixed amount off (per item)</strong> — a set amount off each qualifying item.</li><li><strong>Buy X get Y</strong> — give free quantity when a buy quantity is met.</li></ul><p>Depending on the type you&#39;ll also set the <strong>discount amount</strong>, and for <em>Buy X get Y</em> the <strong>buy quantity</strong> and <strong>maximum eligible quantity</strong> (or a <strong>maximum discounted quantity</strong> for the amount-based types).</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><p>Name the deal, schedule it, and decide how shoppers get it:</p>',4)),a(o,{src:"/images/checkout-deals/details.png",alt:"Checkout deal — Details tab with coupon"}),t[2]||(t[2]=e('<ul><li><strong>Name</strong> and optional <strong>Description</strong>.</li><li><strong>Coupon Type</strong> — <strong>No Coupon</strong> (the deal applies automatically to qualifying carts) or <strong>Specific Coupon</strong> (the customer must enter a code). For a specific coupon you choose whether to <strong>auto-generate</strong> codes or set a single <strong>coupon code</strong>, plus <strong>uses per coupon</strong>.</li><li><strong>Marketing Time</strong> — a <strong>Starts From</strong> / <strong>Ends Till</strong> window.</li></ul><h3 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h3><p>Target the deal and control its limits:</p>',3)),a(o,{src:"/images/checkout-deals/advanced.png",alt:"Checkout deal — Advanced tab with conditions"}),t[3]||(t[3]=e('<ul><li><strong>Conditions</strong> — a rule builder against the <strong>cart</strong> (subtotal, item count, payment/shipping method, shipping address), <strong>cart items</strong> (price, quantity, weight, subtotal), and <strong>products</strong> (category, family, attributes). Combine with <strong>All conditions true</strong> or <strong>Any conditions true</strong>.</li><li><strong>Priority</strong> and <strong>End Other Rules</strong> — ordering against your other deals.</li><li><strong>Uses per customer</strong> — cap how often one customer can use the deal.</li><li><strong>Channels</strong>, <strong>Customer Groups</strong>, and <strong>Status</strong>.</li></ul><p>Select <strong>Save Checkout Deal</strong>.</p><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>When a deal uses a <strong>Specific Coupon</strong> with auto-generation, you can bulk-generate codes from the deal&#39;s <strong>Coupons</strong> screen. The <strong>Generate Coupons</strong> dialog lets you set the <strong>quantity</strong>, <strong>code length</strong>, <strong>format</strong> (alphanumeric / alphabetical / numeric), and an optional <strong>prefix</strong> and <strong>suffix</strong>. Each generated code is listed with how many <strong>times</strong> it&#39;s been <strong>used</strong> and its dates, and codes can be deleted individually.</p><p>Seller coupons get their own box at checkout, separate from the store-wide coupon field — see <a href="/storefront/seller-storefront#one-cart-several-sellers">Seller Storefront</a> for what a shopper sees.</p><h2 id="copying-a-deal" tabindex="-1">Copying a deal <a class="header-anchor" href="#copying-a-deal" aria-label="Permalink to &quot;Copying a deal&quot;">​</a></h2><p>To build a similar promotion quickly, use <strong>Copy</strong> on an existing deal. It duplicates the deal&#39;s settings into a new, <strong>inactive</strong> copy (named &quot;Copy of …&quot;) and opens it for editing — faster than rebuilding a recurring campaign from scratch.</p><h2 id="managing-deals" tabindex="-1">Managing deals <a class="header-anchor" href="#managing-deals" aria-label="Permalink to &quot;Managing deals&quot;">​</a></h2><p>The <strong>Checkout Deals</strong> list shows each deal with its priority, dates, and status, and offers <strong>Edit</strong>, <strong>Copy</strong>, and <strong>Delete</strong> actions.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Reach for a Checkout Deal when the offer depends on the <strong>whole cart</strong> (spend $X, get Y) or needs a <strong>coupon code</strong>. To simply lower the shown price of individual products, use <a href="/marketing/product-discounts">Product Discounts</a> or the <a href="/pricing/manage-pricing">Manage Pricing</a> special price instead.</p></div>',10))])}const k=n(l,[["render",d]]);export{f as __pageData,k as default};
